import type { Metadata } from "next";
import "./globals.css";
import Navbar from "@/components/layout/Navbar";
import Footer from "@/components/layout/Footer";

export const metadata: Metadata = {
  title: "PULSE 3D | Промышленная 3D печать Санкт-Петербург",
  description: "Серийное производство деталей из пластика и нейлона. Парк из 10 скоростных 3D-принтеров Bambu Lab.",
};

import { ModalProvider } from "@/context/ModalContext";
import ContactModal from "@/components/modals/ContactModal";

"use client";

import { usePathname } from 'next/navigation';
import { ModalProvider } from "@/context/ModalContext";
import ContactModal from "@/components/modals/ContactModal";
import Navbar from "@/components/layout/Navbar";
import Footer from "@/components/layout/Footer";

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  const pathname = usePathname();
  const isAdmin = pathname?.startsWith('/admin');

  return (
    <html lang="ru">
      <body className={isAdmin ? 'admin-body' : ''}>
        <ModalProvider>
          {!isAdmin && <div className="bg-grid"></div>}
          {!isAdmin && <Navbar />}
          <main>{children}</main>
          {!isAdmin && <Footer />}
          {!isAdmin && <ContactModal />}
        </ModalProvider>
      </body>
    </html>
  );
}
